TLM.f("Sancti/08-10",{"officium":"S. Laurentii Martyris","rule":["Gloria"],"fallback":"Commune/C2","from":{"GradualeP":"Commune/C2","Tractus":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Ps 95:6"},{"k":"text","la":"Conféssio et pulchritúdo in conspéctu ejus: sánctitas et magnificéntia in sanctificatióne ejus."},{"k":"ref","la":"Ps 95:1"},{"k":"text","la":"Cantáte Dómino cánticum novum: cantáte Dómino, omnis terra."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Conféssio et pulchritúdo in conspéctu ejus: sánctitas et magnificéntia in sanctificatióne ejus."}],"Oratio":[{"k":"text","la":"Da nobis, quǽsumus, omnípotens Deus: vitiórum nostrorum flammas exstínguere; qui beáto Lauréntio tribuísti tormentórum suórum incéndia superáre."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 9:6-10"},{"k":"text","la":"Fratres: Qui parce séminat, parce et metet: et qui séminat in benedictiónibus, de benedictiónibus et metet. Unusquísque prout destinávit in corde suo, non ex tristítia aut ex necessitáte: hilárem enim datórem díligit Deus. Potens est autem Deus omnem grátiam abundáre fácere in vobis, ut, in ómnibus semper omnem sufficiéntiam habéntes, abundétis in omne opus bonum, sicut scriptum est: Dispérsit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi. Qui autem admínistrat semen seminánti: et panem ad manducándum præstábit, et multiplicábit semen vestrum, et augébit increménta frugum justítiæ vestræ."}],"Graduale":[{"k":"ref","la":"Ps 16:3"},{"k":"text","la":"Probásti, Dómine, cor meum, et visitásti nocte."},{"k":"text","la":"Igne me examinásti, et non est invénta in me iníquitas.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Levíta Lauréntius bonum opus operátus est: qui per signum crucis cœcos illuminávit. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 12:24-26"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Amen, amen, dico vobis, nisi granum fruménti cadens in terram, mórtuum fúerit, ipsum solum manet: si autem mórtuum fúerit, multum fructum affert. Qui amat ánimam suam, perdet eam: et qui odit ánimam suam in hoc mundo, in vitam ætérnam custódit eam. Si quis mihi mínistrat, me sequátur: et ubi sum ego, illic et miníster meus erit. Si quis mihi ministráverit, honorificábit eum Pater meus."}],"Offertorium":[{"k":"ref","la":"Ps 95:6"},{"k":"text","la":"Conféssio et pulchritúdo in conspéctu ejus: sánctitas, et magnificéntia in sanctificatióne ejus."}],"Secreta":[{"k":"text","la":"Accipe, quǽsumus, Dómine, múnera dignánter obláta: et, beáti Lauréntii suffragántibus méritis, ad nostræ salútis auxílium proveníre concéde."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joann 12:26"},{"k":"text","la":"Qui mihi mínistrat, me sequátur: et ubi ego sum, illic et miníster meus erit."}],"Postcommunio":[{"k":"text","la":"Sacro múnere satiáti, súpplices te, Dómine, deprecámur: ut, quod débitæ servitútis celebrámus offício, intercedénte beáto Lauréntio Mártyre tuo, salvatiónis tuæ sentiámus augméntum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"7ed6e7c28135b14c":{"t":"Ps 95, 6, Ps 95, 1\n(Ps 95, 6) Slava je i krasota pred licem njegovim, svetost i veličanstvo u svetinji njegovoj. (Ps 95, 1) Pjevajte Gospodinu pjesmu novu, pjevaj Gospodinu sva zemljo!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 95, 6) Slava je i krasota pred licem njegovim, svetost i veličanstvo u svetinji njegovoj.","kn":"(Ps. 95, 6). Slava je i krasota pred licem njegovim, svetost a veličanstvo u svetinji njegovoj. (Ps. 95, 1.) Pjevajte GoiSjpcdinu pjesmu novu, pjevaj Gospodinu sva zemljo! Slava Ocu... Slava...","knRef":"Kniewald 1942, str. 674–675 (snimka 338) (OCR)"},"12bcb74ee4007f86":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, svemogući Bože, da ugasimo vatru naših mana kao što si dao blaženom Lovri da odoli svojim mukama u vatri.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Daj nam, molimo, svemogući Bože, da ugas;imo oganj naših opačina, jer si blaženom Lovri, mučeniku svome, dao da odoli požaru svojih muka, po G. n.","knRef":"Kniewald 1942, str. 674–675 (snimka 338) (OCR)"},"f34e39add4221a96":{"t":"2 Kor 9, 6-10\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo: Braćo, tko malo sije, malo će i žeti; tko obilno sije, obilno će i žeti. Neka svatko dijeli kao što odluči u svojem srcu, ne žalostan ili primoran, jer Bog ljubi vesela dobrotvoritelja. A Bog vam može dati obilje svojih različitih darova da imate svega uvijek dovoljno i sami obilujete za sva dobra djela, kao što je pisano: Razdijeli i dade siromasima; njegova pravda ostaje za sve vijeke. Tko sijaču daje sjeme, dat će i kruh za jelo, i umnožit će sjeme vaše i povećati plodove pravde vaše.","kn":"Čitanje poslanice bi. Pavla apostola Korinćanima (II, 9, 6-19). Braćo! Tko malo sije, malo će i žeti, a tko sije -obilno, i žet će obilno. Neka svaki dijeli, kao što je odlučio u svom srcu, ne žalosno niti prisiljenio-, jer Bog ljubi vesela darivaoca. A BO'g može učiniti, da obilujete -svakom milošću, da imate uvijek svega dovoljno i da -obilujete za sva dobra djela kao što je pisano: Razdijeli i dade siromasima, njegova pravednost -ostaje po sve vijeke. A onaj, koji sijaču daje sjeme, taj će dati i kruh za jelo li umnožit će vaše sjeme i povećati plodove vaše pravednosti.","knRef":"Kniewald 1942, str. 674–675 (snimka 338) (OCR)"},"b0bb2f66a43f66cd":{"t":"Ps 16, 3\nIstražio si, Gospodine, srce moje i pohodio si me noću. Iskušao si me u vatri i nisi našao na meni nikakve krivice.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nĐakon je Lovro dobro djelo činio, jer je znakom križa slijepima vid vraćao. <i>Aleluja</i>.","kn":"(Ps. 16, 3). Kušao si. Gospodine, E-rce moje i ipohodio si me noću: ognjem si me kušao i ,ne nađe se u meni krivica:\n\nAleluja, aleluja. Đakon Lovro dobro djelo učini, jer znakom križa prosvijetli slijepe, aleluja.","knRef":"Kniewald 1942, str. 674–675 (snimka 338) (OCR)"},"78b08a2a7b5143a2":{"t":"Iv 12, 24-26\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus svojim učenicima: Ako pšenično zrno koje padne na zemlju ne istrune, ostaje samo, a ako istrune, daje mnogo ploda. Tko ljubi svoj život izgubit će ga. a tko prezire svoj život na ovome svijetu čuva ga za vječni život. Tko meni služi, neka ide za mnom, i gdje sam ja bit će i moj sluga. Tko meni služi proslavit će ga moj Otac.","kn":"t Slijedi sveto evanđelje po Ivanu (12, 24-26). U ono vrijeme reče Isus svojim učenicima; Ako pšenično zrno, koje pade na zemlju, ne iistrune, ostaje samo,^ a ako istrne, daje mnogo ploda. Tko ljubi SVOJ život, izgubit će ga, a tko mrzi svoj život na ovomu svijetu, čuva ga za vječni život. Tko meni Sluga. Tko meni sluzi, pocastit će ga moj Otac.","knRef":"Kniewald 1942, str. 498–499 (snimka 250) (OCR)"},"9890b3e5038ee192":{"t":"Ps 95, 6\nSlava je i krasota pred licem njegovim, svetost i veličanstvo u svetinji njegovoj.","kn":"(Ps. 95, 6). Slava je i krasotai pred licem njegovim, svetost i veličanstvo u svetinji njegovoj.","knRef":"Kniewald 1942, str. 676–677 (snimka 339) (OCR)"},"6c9dc2a9cc8088a4":{"t":"Primi, Gospodine, darove dostojno prikazane i po zaslugama i zagovoru blaženog Lovre daj da budu na pomoć našemu spasenju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, molimo, Gospodine, darove dostojno prikazane, te zagovorom i zaslugama svetoga Lovre, mučenika svoga,, dopusti, da uskoriste našemu spasenju, po G. n.","knRef":"Kniewald 1942, str. 676–677 (snimka 339) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"9897d36069bd455d":{"t":"Iv 12, 26\nTko mene služi neka me slijedi i gdje sam ja ondje će biti i moj sluga.","kn":"(Iv. 12, 26). Tko meni služi, za mnom neka ide, i gdje sam ja, ondje će biti i moj sluga.","knRef":"Kniewald 1942, str. 676–677 (snimka 339) (OCR)"},"124b80061f6fd3f3":{"t":"<i>Pomolimo se</i>.\nNasićeni svetim darom, ponizno te, molimo, Gospodine, da ono što slavimo službom dužne pokornosti osjetimo po zagovoru blaženoga Lovre mučenika tvoga kao povećanje tvoje milosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
